def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    # Spread the least frequent nonzero color from the object outward by two cells.
    counts = {}
    for r, c in points:
        counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    inner = min(counts, key=counts.get)
    # Expand by the thickness of the surrounding frame (distance to inner color).
    pad = min(min(r - r0, r1 - r, c - c0, c1 - c)
              for r, c in points if grid[r][c] == inner)
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - pad), min(h, r1 + pad + 1)):
        for c in range(max(0, c0 - pad), min(w, c1 + pad + 1)):
            if grid[r][c] == 0:
                out[r][c] = inner
    return out

